<script setup>
import {computed,reactive,ref} from 'vue';
import {t,number,errorText} from '../i18n';
import {quantity} from '../../core/shared.mjs';
import {validateFabricGeometry,shapePoints} from '../../core/fabric-geometry.mjs';
import FormField from './FormField.vue';
const props=defineProps({modelValue:Object,width:Number,height:Number});const emit=defineEmits(['update:modelValue']);
const draft=reactive({target:'defect',type:'rect',x:'0',y:'0',width:'1',height:'1',points:'0 0\n1 0\n1 1'}),error=ref('');
const geometry=computed(()=>props.modelValue??{version:1,frameWidthCm:props.width,frameHeightCm:props.height,offsetXCm:0,offsetYCm:0,complete:false,outline:null,defects:[]});
function update(value){error.value='';try{validateFabricGeometry({widthCm:props.width,heightCm:props.height,geometry:value});emit('update:modelValue',value)}catch(e){const key=e.code??e.message;error.value=t(key)!==key?t(key):errorText(e)}}
function addShape(){try{const g=JSON.parse(JSON.stringify(geometry.value)),point=(x,y)=>({xCm:quantity(x),yCm:quantity(y)});let shape=draft.type==='rect'?{type:'rect',...point(draft.x,draft.y),widthCm:quantity(draft.width,{positive:true}),heightCm:quantity(draft.height,{positive:true})}:{type:'polygon',points:draft.points.trim().split(/\n/).map(line=>{const parts=line.trim().split(/\s+/);if(parts.length!==2)throw Object.assign(Error('fabric_geometry_invalid'),{code:'fabric_geometry_invalid'});return point(...parts)})};if(!shapePoints(shape).every(([x,y])=>x<=props.width&&y<=props.height))throw Object.assign(Error('fabric_geometry_bounds'),{code:'fabric_geometry_bounds'});if(shape.type==='rect'){shape.xCm=quantity(shape.xCm+g.offsetXCm);shape.yCm=quantity(shape.yCm+g.offsetYCm)}else shape.points=shape.points.map(p=>({xCm:quantity(p.xCm+g.offsetXCm),yCm:quantity(p.yCm+g.offsetYCm)}));if(draft.target==='outline')g.outline=shape;else g.defects.push(shape);update(g)}catch(e){const key=e.code??e.message;error.value=t(key)!==key?t(key):errorText(e)}}
function remove(index){const g=JSON.parse(JSON.stringify(geometry.value));if(index===-1)g.outline=null;else g.defects.splice(index,1);update(g)}
const shapeText=shape=>shapePoints(shape).map(([x,y])=>`${number(x-geometry.value.offsetXCm,6)} ${number(y-geometry.value.offsetYCm,6)}`).join(' · ');
</script>
<template><section class="form-section wide"><h3>{{t('fabricMeasuredGeometry')}}</h3><p class="field-help">{{t('fabricGeometryHelp')}}</p><p v-if="geometry.offsetXCm||geometry.offsetYCm||geometry.frameWidthCm!==width||geometry.frameHeightCm!==height" class="notice">{{t('fabricInheritedGeometry')}}</p><p v-if="error" class="notice error" role="alert">{{error}}</p><div class="form-grid"><FormField :label="t('fabricShapeRole')" v-slot="{id}"><select :id="id" v-model="draft.target"><option value="defect">{{t('fabricUnavailableShape')}}</option><option value="outline">{{t('fabricOutlineShape')}}</option></select></FormField><FormField :label="t('fabricShapeType')" v-slot="{id}"><select :id="id" v-model="draft.type"><option value="rect">{{t('fabricRectangleShape')}}</option><option value="polygon">{{t('fabricPolygonShape')}}</option></select></FormField><template v-if="draft.type==='rect'"><FormField v-for="key in ['x','y','width','height']" :key="key" :label="`${t('fabricShape_'+key)} (cm)`" v-slot="{id}"><input :id="id" v-model="draft[key]" inputmode="decimal"/></FormField></template><FormField v-else :label="t('fabricPolygonCoordinates')" wide v-slot="{id}"><textarea :id="id" v-model="draft.points" rows="5" maxlength="1500"/><p class="field-help">{{t('fabricPolygonHelp')}}</p></FormField></div><button class="button small" type="button" :disabled="draft.target==='defect'&&geometry.defects.length>=16" @click="addShape">{{t('fabricAddMeasuredShape')}}</button><div v-if="geometry.outline" class="stat-row"><span>{{t('fabricOutlineShape')}}<small class="cell-subtitle">{{shapeText(geometry.outline)}}</small></span><button class="button text small" type="button" @click="remove(-1)">{{t('remove')}}</button></div><div v-for="(shape,index) in geometry.defects" :key="index" class="stat-row"><span>{{t('fabricUnavailableShape')}} {{index+1}}<small class="cell-subtitle">{{shapeText(shape)}}</small></span><button class="button text small" type="button" :aria-label="`${t('remove')} ${t('fabricUnavailableShape')} ${index+1}`" @click="remove(index)">{{t('remove')}}</button></div><label class="checkbox-label"><input type="checkbox" :checked="geometry.complete" @change="update({...geometry,complete:$event.target.checked})"/>{{t('fabricMappingComplete')}}</label></section></template>
